  // Initial result: empty prefix + best suffix found
  let res = n - suffixPtr;

  let prefixBad = 0; // bad days in prefix
  for (let prefixPtr = 0; prefixPtr < n; prefixPtr++) {
    if (projectedSales[prefixPtr] < 10) {
      prefixBad++;
    }

    // Shrink suffix to maintain constraint:
